"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { useId, useRef, useState } from "react";

import { NumberTicker } from "@/components/motion/number-ticker";
import { SegmentedControl } from "@/components/motion/segmented-control";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";

import { formatCompact } from "../lib/format";
import { usePointCursor } from "../lib/use-point-cursor";
import { BlockFrame } from "../parts/block-frame";
import { Delta } from "../parts/delta";
import { BellIcon, ChevronDownIcon, packIcon } from "../parts/icons";
import { TrendChart } from "../parts/trend-chart";
import { DepositIcon, EyeIcon, EyeOffIcon, SendIcon } from "./icons";
import { formatDollars } from "./money";
import { ActionPanel } from "./wallet-card/action-panel";
import { ActivityList } from "./wallet-card/activity-list";
import { ACTION_ORDER, ACTIONS, type Activity, type MoneyAction, pinToBalance, RANGE_AXIS, RANGES, WALLETS, type WalletRange } from "./wallet-card/data";
import { pointDay } from "./wallet-card/point-day";

const SearchIcon = packIcon("search");
const SwapIcon = packIcon("refresh");
const BillIcon = packIcon("credit-card");
const ACTION_ICON = { send: SendIcon, deposit: DepositIcon, move: SwapIcon, pay: BillIcon } satisfies Record<MoneyAction, ReturnType<typeof packIcon>>;
const CURRENCY: Intl.NumberFormatOptions = { style: "currency", currency: "USD" };

interface Ledger {
  balance: number;
  activity: Activity[];
}

/**
 * A clinic's wallet: switch clinic, read the balance or hide it, follow the
 * balance over a week, month or year, move money, and scan recent payments.
 * A confirmed action adds its row at once and the balance rolls to match.
 */
export function WalletCard({ className }: { className?: string }) {
  const titleId = useId();
  const reduceMotion = useReducedMotion();
  const [walletId, setWalletId] = useState(WALLETS[0]!.id);
  const [ledgers, setLedgers] = useState<Record<string, Ledger>>(() =>
    Object.fromEntries(WALLETS.map((wallet) => [wallet.id, { balance: wallet.balance, activity: wallet.activity }])),
  );
  const [range, setRange] = useState<WalletRange>("month");
  const [hidden, setHidden] = useState(false);
  const [action, setAction] = useState<MoneyAction | null>(null);
  const [searching, setSearching] = useState(false);
  const [query, setQuery] = useState("");
  const [showAll, setShowAll] = useState(false);
  const [unread, setUnread] = useState(2);
  const nextId = useRef(1);

  const wallet = WALLETS.find((item) => item.id === walletId) ?? WALLETS[0]!;
  const ledger = ledgers[wallet.id] ?? { balance: wallet.balance, activity: wallet.activity };
  const values = pinToBalance(wallet.trend[range], ledger.balance);
  const cursor = usePointCursor(values.length, range === "month" ? 7 : 3);

  const matches = ledger.activity.filter((row) => row.source.toLowerCase().includes(query.trim().toLowerCase()));
  const rows = showAll || query ? matches : matches.slice(0, 4);

  const confirm = (amount: number) => {
    if (!action) return;
    const spec = ACTIONS[action];
    const signed = spec.sign * amount;
    const row: Activity = { id: `new-${nextId.current++}`, kind: spec.kind, source: spec.source, date: "Today", amount: signed };
    setLedgers((current) => ({
      ...current,
      [wallet.id]: { balance: Math.round((ledger.balance + signed) * 100) / 100, activity: [row, ...ledger.activity] },
    }));
    setAction(null);
  };

  const describe = (index: number) => `${pointDay(range, index, values.length)}: ${formatDollars(values[index] ?? 0)}`;

  return (
    <BlockFrame aria-labelledby={titleId} className={cn("mx-auto max-w-xl", className)}>
      <h2 id={titleId} className="sr-only">
        Clinic wallet
      </h2>
      <header className="flex items-center justify-between gap-2 border-b border-border px-4 py-3">
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button variant="ghost" size="sm" aria-label={`Wallet: ${wallet.name}`}>
              {wallet.name}
              <ChevronDownIcon aria-hidden="true" className="size-4" />
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="start">
            <DropdownMenuRadioGroup
              value={walletId}
              onValueChange={(next) => {
                setWalletId(next);
                setAction(null);
              }}
            >
              {WALLETS.map((item) => (
                <DropdownMenuRadioItem key={item.id} value={item.id}>
                  {item.name}
                </DropdownMenuRadioItem>
              ))}
            </DropdownMenuRadioGroup>
          </DropdownMenuContent>
        </DropdownMenu>
        <div className="flex items-center gap-1">
          <Button
            variant="ghost"
            size="icon"
            aria-label="Search payments"
            aria-expanded={searching}
            onClick={() => {
              setSearching((open) => !open);
              setQuery("");
            }}
          >
            <SearchIcon aria-hidden="true" className="size-4" />
          </Button>
          <Button
            variant="ghost"
            size="icon"
            aria-label={unread ? `Notifications, ${unread} unread` : "Notifications, none unread"}
            onClick={() => setUnread(0)}
          >
            <BellIcon aria-hidden="true" className="size-4" />
            {unread ? <span aria-hidden="true" className="absolute top-1.5 right-1.5 size-2 rounded-full bg-chart-3" /> : null}
          </Button>
        </div>
      </header>

      <div className="flex flex-col gap-5 p-4">
        <div className="flex items-start justify-between gap-3">
          <div className="flex flex-col gap-1">
            <span className="text-sm text-muted-foreground">Available balance</span>
            <span aria-live="polite" className="flex items-baseline gap-2 text-3xl font-semibold tracking-tight">
              {hidden ? (
                <span aria-label="Balance hidden">$ ******</span>
              ) : (
                <NumberTicker value={ledger.balance} format={CURRENCY} />
              )}
              <span className="text-sm font-normal text-muted-foreground">USD</span>
            </span>
            <span className="flex items-center gap-1.5 text-xs text-muted-foreground">
              <Delta value={wallet.change} />
              this month
            </span>
          </div>
          <Button variant="ghost" size="icon" aria-pressed={hidden} aria-label="Hide amounts" onClick={() => setHidden((value) => !value)}>
            {hidden ? <EyeOffIcon aria-hidden="true" className="size-4" /> : <EyeIcon aria-hidden="true" className="size-4" />}
          </Button>
        </div>

        <div className="flex flex-col gap-2">
          <SegmentedControl aria-label="Balance range" options={RANGES} value={range} onValueChange={setRange} className="self-start" />
          <TrendChart
            label={`Balance over the last ${range}`}
            values={values}
            compare={null}
            axisLabels={RANGE_AXIS[range]}
            formatAxis={(value) => `$${formatCompact(value)}`}
            describePoint={describe}
            pointDetails={(index) => ({
              title: pointDay(range, index, values.length),
              rows: [{ label: "Balance", value: hidden ? "Hidden" : formatDollars(values[index] ?? 0), marker: "bg-chart-1" }],
            })}
            summary={`${wallet.name} balance, last ${range}`}
            cursor={cursor}
            className="[&_[role=application]]:min-h-36"
          />
        </div>

        <div role="group" aria-label="Move money" className="grid grid-cols-4 gap-2">
          {ACTION_ORDER.map((key) => {
            const Icon = ACTION_ICON[key];
            return (
              <Button
                key={key}
                variant={action === key ? "secondary" : "outline"}
                aria-expanded={action === key}
                onClick={() => setAction((current) => (current === key ? null : key))}
                className="h-16"
              >
                <span className="flex flex-col items-center gap-1.5 text-xs">
                  <Icon aria-hidden="true" className="size-4" />
                  {ACTIONS[key].label}
                </span>
              </Button>
            );
          })}
        </div>

        <AnimatePresence mode="wait" initial={false}>
          {action ? (
            <motion.div
              key={`${wallet.id}-${action}`}
              initial={reduceMotion ? { opacity: 0 } : { opacity: 0, y: 8 }}
              animate={{ opacity: 1, y: 0 }}
              exit={reduceMotion ? { opacity: 0 } : { opacity: 0, y: -4 }}
              transition={{ duration: 0.18, ease: [0.165, 0.84, 0.44, 1] }}
            >
              <ActionPanel action={action} balance={ledger.balance} onConfirm={confirm} onCancel={() => setAction(null)} />
            </motion.div>
          ) : null}
        </AnimatePresence>

        <section aria-labelledby={`${titleId}-activity`} className="flex flex-col gap-2">
          <div className="flex items-center justify-between gap-2">
            <h3 id={`${titleId}-activity`} className="text-sm font-medium">
              Recent activity
            </h3>
            {query ? null : (
              <Button variant="ghost" size="sm" aria-expanded={showAll} onClick={() => setShowAll((value) => !value)}>
                {showAll ? "Show fewer" : "View all"}
              </Button>
            )}
          </div>
          {searching ? (
            <Input
              autoFocus
              aria-label="Search payments by name"
              placeholder="Search by patient, insurer or supplier"
              value={query}
              onChange={(event) => setQuery(event.target.value)}
              onKeyDown={(event) => {
                if (event.key === "Escape") {
                  setSearching(false);
                  setQuery("");
                }
              }}
              className="h-8"
            />
          ) : null}
          <ActivityList rows={rows} hidden={hidden} />
        </section>
      </div>
    </BlockFrame>
  );
}

const WHOLE = new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 });
const ONE_PLACE = new Intl.NumberFormat("en-US", { minimumFractionDigits: 1, maximumFractionDigits: 1 });
const COMPACT = new Intl.NumberFormat("en-US", { notation: "compact", maximumFractionDigits: 1 });
const MONEY = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 0 });

/** A whole number with thousands separators. */
export const formatWhole = (value: number) => WHOLE.format(Math.round(value));

/** A number with one decimal place. */
export const formatOnePlace = (value: number) => ONE_PLACE.format(value);

/** A short number for an axis, such as 1.2K. */
export const formatCompact = (value: number) => COMPACT.format(value);

/** A dollar amount with no cents. */
export const formatMoney = (value: number) => MONEY.format(Math.round(value));

/** A percent with one decimal place and no sign. */
export const formatPercent = (value: number) => `${ONE_PLACE.format(Math.abs(value))}%`;

const DAY = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", timeZone: "UTC" });
const WEEKDAY = new Intl.DateTimeFormat("en-US", { weekday: "long", timeZone: "UTC" });

/** The sample data ends on this day, so every block shows the same dates on every render. */
export const SAMPLE_END = Date.UTC(2026, 9, 31);

/** The date `daysBeforeEnd` days before the last sample day. */
export const sampleDate = (daysBeforeEnd: number) => new Date(SAMPLE_END - daysBeforeEnd * 86_400_000);

/** A short date, such as Oct 31. */
export const formatDay = (date: Date) => DAY.format(date);

/** A weekday name, such as Tuesday. */
export const formatWeekday = (date: Date) => WEEKDAY.format(date);

"use client";

import { type KeyboardEvent, type PointerEvent, useCallback, useState } from "react";

/** What a chart needs to let a person inspect one point with a pointer or the keyboard. */
export interface PointCursor {
  /** The inspected point, or null when nothing is inspected. */
  index: number | null;
  setIndex: (index: number | null) => void;
  /** Spread onto the focusable plot. Arrows step, Page keys jump, Home and End go to the ends, Escape clears. */
  plotProps: {
    tabIndex: 0;
    onKeyDown: (event: KeyboardEvent<HTMLElement>) => void;
    /** A tap or a press inspects the point under it, so a touch screen needs no hover. */
    onPointerDown: (event: PointerEvent<HTMLElement>) => void;
    onPointerMove: (event: PointerEvent<HTMLElement>) => void;
    onPointerLeave: (event: PointerEvent<HTMLElement>) => void;
    /** A finger can scrub across the plot while the page still scrolls up and down. */
    style: { touchAction: "pan-y" };
    onBlur: () => void;
  };
}

/**
 * Tracks the inspected point of a plot with `length` points. `pageStep` is how
 * far the Page keys and Shift with an arrow jump.
 */
export function usePointCursor(length: number, pageStep = 7): PointCursor {
  const [raw, setIndex] = useState<number | null>(null);
  // A shorter range can leave the cursor past the end, so clamp on read.
  const index = raw === null ? null : Math.min(raw, length - 1);

  const onKeyDown = useCallback(
    (event: KeyboardEvent<HTMLElement>) => {
      const last = length - 1;
      const current = index ?? last;
      const big = event.shiftKey ? pageStep : 1;
      let next: number | null;
      if (event.key === "ArrowLeft") next = index === null ? last : Math.max(0, current - big);
      else if (event.key === "ArrowRight") next = index === null ? last : Math.min(last, current + big);
      else if (event.key === "PageUp") next = Math.max(0, current - pageStep);
      else if (event.key === "PageDown") next = Math.min(last, current + pageStep);
      else if (event.key === "Home") next = 0;
      else if (event.key === "End") next = last;
      else if (event.key === "Escape" && index !== null) next = null;
      else return;
      event.preventDefault();
      setIndex(next);
    },
    [index, length, pageStep],
  );

  const onPointerMove = useCallback(
    (event: PointerEvent<HTMLElement>) => {
      const box = event.currentTarget.getBoundingClientRect();
      if (box.width === 0) return;
      const ratio = Math.min(1, Math.max(0, (event.clientX - box.left) / box.width));
      setIndex(Math.round(ratio * (length - 1)));
    },
    [length],
  );

  const clear = useCallback(() => setIndex(null), []);

  // A finger leaves the plot the moment it lifts. Clearing then would hide the point a tap just chose,
  // so only a mouse clears on the way out. A tapped point stays until the plot loses focus.
  const onPointerLeave = useCallback((event: PointerEvent<HTMLElement>) => {
    if (event.pointerType === "mouse") setIndex(null);
  }, []);

  return {
    index,
    setIndex,
    plotProps: {
      tabIndex: 0,
      onKeyDown,
      onPointerDown: onPointerMove,
      onPointerMove,
      onPointerLeave,
      onBlur: clear,
      style: { touchAction: "pan-y" },
    },
  };
}

import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

import { ArrowDownIcon, ArrowUpIcon } from "@/components/blocks/parts/icons";
import { cn } from "@/lib/utils";

import { formatPercent } from "../lib/format";
import { STATUS_TEXT } from "../lib/status";

/** Props for a change figure. */
export interface DeltaProps {
  /** The percent change. */
  value: number;
  /** Set when a fall is the good direction, such as no-shows or waiting time. */
  lowerIsBetter?: boolean;
  className?: string;
}

/**
 * A percent change with an arrow. The arrow and the spoken word carry the
 * direction, and the colour says only whether the change is good.
 */
export function Delta({ value, lowerIsBetter = false, className }: DeltaProps) {
  const flat = Math.abs(value) < 0.05;
  const up = value > 0;
  const good = flat ? null : up !== lowerIsBetter;
  const Arrow = up ? ArrowUpIcon : ArrowDownIcon;
  return (
    <span
      className={cn(
        "inline-flex items-center gap-0.5 text-xs font-medium tabular-nums",
        good === null ? "text-muted-foreground" : STATUS_TEXT[good ? "good" : "bad"],
        className,
      )}
    >
      {flat ? null : <Arrow aria-hidden="true" className="size-3" />}
      <span className="sr-only">{flat ? "No change" : up ? "Up" : "Down"}</span>
      {formatPercent(value)}
    </span>
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

/** A warning triangle, from the chosen icon pack. */
