/** Two arrows that cross, for swapping two things. */
export const ArrowsShuffleIcon = ownIcon(
  <>
    <path d="M2 4.5h2.2c1.2 0 2.3.6 3 1.6l1.6 3.8c.7 1 1.8 1.6 3 1.6H14" />
    <path d="M2 11.5h2.2c1 0 1.9-.4 2.6-1.1M9.2 5.6c.7-.7 1.6-1.1 2.6-1.1H14" />
    <path d="M12 2.5l2 2-2 2M12 9.5l2 2-2 2" />
  </>,
);

/** Six dots, for a handle a person drags. */
export const GripVerticalIcon = ownIcon(
  <path d="M6 3.5h.01M10 3.5h.01M6 8h.01M10 8h.01M6 12.5h.01M10 12.5h.01" strokeWidth="2" />,
);

/** Two bars, for pause. */
export const PlayerPauseFilledIcon = ownIcon(<path d="M5.5 3.5v9M10.5 3.5v9" strokeWidth="2.5" />);

/** A bin, for remove. */
export const TrashIcon = ownIcon(
  <>
    <path d="M2.5 4.5h11M6 4.5V3a.5.5 0 0 1 .5-.5h3A.5.5 0 0 1 10 3v1.5" />
    <path d="M4 4.5l.6 8a1 1 0 0 0 1 .9h4.8a1 1 0 0 0 1-.9l.6-8M6.75 7v4M9.25 7v4" />
  </>,
);

/** The three states a figure or a row can be in. */
export type Status = "good" | "watch" | "bad";

/** The text colour for each state. Each one passes 4.5 to 1 on a card in both themes. */
export const STATUS_TEXT = {
  good: "text-marketing-green-ink",
  watch: "text-marketing-amber-ink",
  bad: "text-marketing-orange-ink",
} satisfies Record<Status, string>;

/** A tinted surface for each state, for a pill or a cell. Pair it with the matching text colour. */
export const STATUS_SURFACE = {
  good: "bg-marketing-green-surface",
  watch: "bg-marketing-amber-surface",
  bad: "bg-marketing-orange-surface",
} satisfies Record<Status, string>;

/** The word a screen reader and a label use for each state. Colour never carries a state alone. */
export const STATUS_WORD = {
  good: "Good",
  watch: "Watch",
  bad: "At risk",
} satisfies Record<Status, string>;

"use client";

import { motion, useReducedMotion, type Transition } from "motion/react";

import { cn } from "@/lib/utils";

import { areaPath, axisTicks, linePath, paddedExtent, toX, toY } from "../lib/plot";
import type { PointCursor } from "../lib/use-point-cursor";
import { PointTip, type PointTipProps } from "./point-tip";
import type { VarStyle } from "@/components/blocks/lib/css-vars";

/** Props for a trend chart. */
export interface TrendChartProps {
  /** Names the chart for screen readers, such as "Bookings, last 30 days". */
  label: string;
  values: number[];
  /** The earlier period, drawn as a dashed line. Null hides it. */
  compare: number[] | null;
  /** A short label for the first, middle and last point of the axis. */
  axisLabels: [string, string, string];
  formatAxis: (value: number) => string;
  /** The sentence shown for the inspected point, also read to screen readers. */
  describePoint: (index: number) => string;
  /** The details shown in the card beside the inspected point. Without it, the sentence above the plot changes instead. */
  pointDetails?: (index: number) => Pick<PointTipProps, "title" | "rows" | "note">;
  /** The sentence shown when no point is inspected. */
  summary: string;
  cursor: PointCursor;
  className?: string;
}

// Critically damped: the line settles on its new shape with no wobble.
const MORPH: Transition = { type: "spring", stiffness: 260, damping: 32, mass: 1 };
const INSTANT: Transition = { duration: 0 };

/**
 * One line over time with an optional earlier period behind it. The plot is a
 * single tab stop: arrows inspect a point, Home and End jump, Escape clears.
 * The readout sits above the plot, so it never covers the line it describes.
 */
export function TrendChart({
  label,
  values,
  compare,
  axisLabels,
  formatAxis,
  describePoint,
  pointDetails,
  summary,
  cursor,
  className,
}: TrendChartProps) {
  const reduceMotion = useReducedMotion();
  const transition = reduceMotion ? INSTANT : MORPH;
  const extent = paddedExtent(compare ? [values, compare] : [values]);
  const ticks = axisTicks(extent).reverse();
  const { index } = cursor;
  const pointValue = index === null ? null : values[index];

  return (
    <div className={cn("flex min-h-0 flex-1 flex-col gap-3", className)}>
      <p className="h-5 truncate text-sm text-muted-foreground">{index === null || pointDetails ? summary : describePoint(index)}</p>
