      <div className="flex justify-end gap-2">
        <Button type="button" variant="ghost" size="sm" onClick={onCancel}>
          Cancel
        </Button>
        <Button type="button" size="sm" disabled={short} onClick={() => onConfirm(value)}>
          {spec.label} {formatDollars(value)}
        </Button>
