export interface ActivityListProps {
  rows: Activity[];
  /** Hides each amount, as the balance does. */
  hidden: boolean;
}

/**
 * Recent money in and out, newest first. A new row opens in place at the
 * top. Each amount carries its sign in text, so colour never says the
 * direction alone.
 */
export function ActivityList({ rows, hidden }: ActivityListProps) {
  const reduceMotion = useReducedMotion();
  if (rows.length === 0) return <p className="py-6 text-center text-sm text-muted-foreground">No payments match that search.</p>;
  return (
    <ul className="flex flex-col">
      <AnimatePresence initial={false}>
        {rows.map((row) => {
          const Icon = KIND_ICON[row.kind];
          return (
            <motion.li
              key={row.id}
              initial={reduceMotion ? { opacity: 0 } : { opacity: 0, height: 0 }}
              animate={reduceMotion ? { opacity: 1 } : { opacity: 1, height: "auto" }}
              exit={reduceMotion ? { opacity: 0 } : { opacity: 0, height: 0 }}
              transition={{ duration: 0.24, ease: [0.165, 0.84, 0.44, 1] }}
              className="overflow-hidden"
            >
              <div className="group relative isolate flex items-center gap-3 px-2 py-2.5">
                <span aria-hidden="true" className="absolute inset-0 -z-10 rounded-lg group-hover:bg-muted/60" />
                <span className={cn("grid size-8 shrink-0 place-items-center rounded-full", KIND_TINT[row.kind])}>
                  <Icon aria-hidden="true" className="size-4" />
                </span>
                <span className="flex min-w-0 flex-1 flex-col">
                  <span className="truncate text-sm font-medium">{row.source}</span>
                  <span className="text-xs text-muted-foreground">{row.date}</span>
                </span>
                <span className={cn("text-sm font-medium tabular-nums", row.amount > 0 ? STATUS_TEXT.good : "text-foreground")}>
                  {hidden ? "Hidden" : formatSigned(row.amount)}
                </span>
              </div>
            </motion.li>
          );
        })}
      </AnimatePresence>
    </ul>
  );
}

import type { WalletRange } from "./data";

const DAY = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", timeZone: "UTC" });
const MONTH = new Intl.DateTimeFormat("en-US", { month: "long", year: "numeric", timeZone: "UTC" });
const TODAY = Date.UTC(2026, 10, 11);

/** The date of one point on the balance line: a day for a week or month, a month for a year. */
export function pointDay(range: WalletRange, index: number, length: number): string {
  const back = length - 1 - index;
  if (range === "year") return MONTH.format(new Date(Date.UTC(2026, 10 - back, 1)));
  return DAY.format(new Date(TODAY - back * 86_400_000));
}
